<script setup>
import CompanyField from '@/Components/CompanyField.vue';
import BulkCompanyAssignment from '@/Components/BulkCompanyAssignment.vue';
import { useCompanySelection } from '@/Composables/useCompanySelection';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import CustomSelect from '@/Components/CustomSelect.vue';
import { Head, Link, router } from '@inertiajs/vue3';
import { computed, reactive, watch } from 'vue';

const props = defineProps({
    rentals: Object, summary: Object, filters: Object, categoryOptions: Array, section1Options: Array,
    section2Options: Array, locationOptions: Array, supplierOptions: Array, statusOptions: Array, dueOptions: Array, canEdit: Boolean,
});
const form = reactive({ ...props.filters });
watch(() => props.filters, value => Object.assign(form, value));
const activeFilters = computed(() => Object.values(form).filter((value) => value !== '' && value !== null).length);
const applyFilters = () => router.get(route('miri-rental.index'), form, { preserveState: true, preserveScroll: true, replace: true });
const clearFilters = () => { Object.keys(form).forEach((key) => { form[key] = ''; }); applyFilters(); };
const toggleMissing = () => { form.missing_details = form.missing_details === 'missing' ? '' : 'missing'; applyFilters(); };
const daysRemaining = (value) => value ? Math.ceil((new Date(`${value}T00:00:00`) - new Date(new Date().toLocaleDateString('en-CA'))) / 86400000) : null;
const dueLabel = (value) => { const days = daysRemaining(value); return days === null ? 'No due date' : days < 0 ? `${Math.abs(days)} days overdue` : days === 0 ? 'Due today' : `${days} days left`; };
const dueTone = (value) => { const days = daysRemaining(value); return days !== null && days < 0 ? 'text-red-600' : days !== null && days <= 7 ? 'text-amber-600' : days !== null && days <= 30 ? 'text-orange-600' : 'text-emerald-600'; };
const rowTone = (value) => { const days = daysRemaining(value); return days !== null && days < 0 ? 'bg-red-50/70' : days !== null && days <= 7 ? 'bg-amber-50/60' : ''; };
const { selectedIds, allSelected } = useCompanySelection(() => props.rentals.data);
</script>

<template>
    <Head title="Miri Rental Register" />
    <AuthenticatedLayout>
        <section class="space-y-6">
            <header class="flex flex-wrap items-end justify-between gap-4 rounded-[2rem] border border-[#d8e7d4] bg-white p-7 shadow-sm"><div><p class="text-xs font-bold uppercase tracking-[.25em] text-[#4f9f4a]">Miri Inventory</p><h1 class="mt-2 text-3xl font-bold text-[#234222]">Rental Register</h1><p class="mt-2 text-sm text-[#60745d]">Rental equipment, COG movements, suppliers, and due-date alerts.</p></div><div v-if="canEdit" class="flex gap-2"><Link :href="route('miri-rental.import')" class="rounded-full border border-[#4f9f4a] px-5 py-3 text-sm font-bold text-[#2f7d32]">Import Rental CSV</Link><Link :href="route('miri-rental.create')" class="rounded-full bg-[#4f9f4a] px-5 py-3 text-sm font-bold text-white">Register rental</Link></div></header>
            <section class="grid grid-cols-2 gap-3 sm:grid-cols-4 lg:grid-cols-7"><div v-for="card in [{label:'Total rentals',value:summary.total,color:'border-t-slate-500'},{label:'On hire',value:summary.on_hire,color:'border-t-emerald-500'},{label:'Issued',value:summary.issued,color:'border-t-blue-500'},{label:'Backloaded',value:summary.backload,color:'border-t-violet-500'},{label:'Overdue',value:summary.overdue,color:'border-t-red-500'},{label:'Due in 7 days',value:summary.due_7,color:'border-t-amber-500'},{label:'No due date',value:summary.no_due_date,color:'border-t-slate-400'}]" :key="card.label" class="rounded-2xl border border-[#d8e7d4] border-t-4 bg-white p-4 shadow-sm" :class="card.color"><p class="text-[10px] font-bold uppercase tracking-wider text-[#60745d]">{{ card.label }}</p><p class="mt-2 text-2xl font-black text-[#234222]">{{ card.value }}</p></div></section>
            <form class="rounded-[1.7rem] border border-[#d8e7d4] bg-white p-5 shadow-sm" @submit.prevent="applyFilters"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="font-bold text-[#234222]">Filter rentals</h2><p class="mt-1 text-xs text-[#7f9a7a]">Apply filters to update results and available options. Options follow the search and other selected filters.</p></div><div class="flex gap-2"><button v-if="activeFilters" type="button" class="rounded-xl border border-[#d8e7d4] px-4 py-2 text-sm font-semibold text-[#60745d]" @click="clearFilters">Clear all</button><button type="submit" class="rounded-xl bg-[#4f9f4a] px-5 py-2 text-sm font-bold text-white">Apply filters</button></div></div><div class="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-8"><CompanyField v-model="form.company" filter /><label class="sm:col-span-2"><span class="filter-label">Search</span><input v-model.trim="form.search" type="search" class="filter-input" placeholder="Serial, description, supplier, COG or project" /></label><label><span class="filter-label">Category</span><CustomSelect v-model="form.category" class="filter-input"><option value="">All categories</option><option v-if="form.category && !categoryOptions.includes(form.category)" :value="form.category" disabled>{{ form.category }} (no matching records)</option><option v-for="option in categoryOptions" :key="option" :value="option">{{ option }}</option></CustomSelect></label><label><span class="filter-label">Location</span><CustomSelect v-model="form.location" class="filter-input"><option value="">All locations</option><option v-if="form.location && !locationOptions.includes(form.location)" :value="form.location" disabled>{{ form.location }} (no matching records)</option><option v-for="option in locationOptions" :key="option" :value="option">{{ option }}</option></CustomSelect></label><label><span class="filter-label">Supplier</span><CustomSelect v-model="form.supplier" class="filter-input"><option value="">All suppliers</option><option v-if="form.supplier && !supplierOptions.includes(form.supplier)" :value="form.supplier" disabled>{{ form.supplier }} (no matching records)</option><option v-for="option in supplierOptions" :key="option" :value="option">{{ option }}</option></CustomSelect></label><label><span class="filter-label">Status</span><CustomSelect v-model="form.status" class="filter-input"><option value="">All statuses</option><option v-if="form.status && !statusOptions.includes(form.status)" :value="form.status" disabled>{{ form.status }} (no matching records)</option><option v-for="option in statusOptions" :key="option" :value="option">{{ option }}</option></CustomSelect></label><label><span class="filter-label">Due-date alert</span><CustomSelect v-model="form.due_status" class="filter-input"><option value="">All due dates</option><option v-if="dueOptions.includes('overdue') || form.due_status === 'overdue'" :disabled="!dueOptions.includes('overdue')" value="overdue">Overdue</option><option v-if="dueOptions.includes('due_7') || form.due_status === 'due_7'" :disabled="!dueOptions.includes('due_7')" value="due_7">Due within 7 days</option><option v-if="dueOptions.includes('due_30') || form.due_status === 'due_30'" :disabled="!dueOptions.includes('due_30')" value="due_30">Due in 8–30 days</option><option v-if="dueOptions.includes('later') || form.due_status === 'later'" :disabled="!dueOptions.includes('later')" value="later">Due later</option><option v-if="dueOptions.includes('no_date') || form.due_status === 'no_date'" :disabled="!dueOptions.includes('no_date')" value="no_date">No due date</option></CustomSelect></label><div><span class="filter-label">Data quality</span><button type="button" class="flex w-full items-center justify-center gap-2 rounded-xl border px-3 py-2 text-sm font-bold" :class="form.missing_details === 'missing' ? 'border-amber-400 bg-amber-50 text-amber-800' : 'border-[#d8e7d4] bg-white text-[#60745d]'" @click="toggleMissing">{{ form.missing_details === 'missing' ? 'Missing details' : 'Show missing details' }}</button></div></div></form>
            <BulkCompanyAssignment v-if="canEdit" :ids="selectedIds" register="rental" @assigned="selectedIds = []" />
            <div class="overflow-hidden rounded-[1.7rem] border border-[#d8e7d4] bg-white"><div class="border-b border-[#edf3eb] px-5 py-3 text-sm text-[#60745d]"><strong class="text-[#234222]">{{ rentals.total }}</strong> rentals found <span v-if="rentals.total"> · Showing {{ rentals.from }}–{{ rentals.to }}</span></div><div class="overflow-x-auto"><table class="table"><thead><tr><th v-if="canEdit"><input v-model="allSelected" type="checkbox" aria-label="Select all items on this page" /></th><th>Company</th><th>Serial / Tag</th><th>Description</th><th>Supplier / Project</th><th>Location</th><th>Due date</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="item in rentals.data" :key="item.id" :class="rowTone(item.rental_due_date)"><td v-if="canEdit"><input v-model="selectedIds" type="checkbox" :value="item.id" :aria-label="'Select record #' + item.id" /></td><td>{{ item.company || 'Not assigned' }}</td><td><Link class="font-bold text-[#2f7d32]" :href="route('miri-rental.show', item.id)">{{ item.serial_tag_equipment_no || '-' }}</Link></td><td>{{ item.description || '-' }}<div class="text-xs text-slate-500">{{ item.category || '-' }}</div></td><td>{{ item.supplier || '-' }}<div class="text-xs text-slate-500">{{ item.project_contract || '-' }}</div></td><td>{{ item.current_location || '-' }}</td><td><strong :class="dueTone(item.rental_due_date)" class="block">{{ item.rental_due_date || '-' }}</strong><span class="text-xs font-semibold" :class="dueTone(item.rental_due_date)">{{ dueLabel(item.rental_due_date) }}</span></td><td>{{ item.status || '-' }}</td><td><Link class="btn btn-xs" :href="route('miri-rental.show', item.id)">View</Link><Link v-if="canEdit" class="btn btn-xs border-[#cfe6c8] bg-white" :href="route('miri-rental.edit', item.id)">Edit</Link></td></tr><tr v-if="!rentals.data.length"><td :colspan="8 + (canEdit ? 1 : 0)" class="py-12 text-center text-slate-500">No Rental records match the selected filters.</td></tr></tbody></table></div></div>
            <div class="flex flex-wrap gap-2"><Link v-for="link in rentals.links" :key="link.label" v-html="link.label" :href="link.url || '#'" class="btn btn-sm" :class="{ 'btn-disabled': !link.url, 'btn-success text-white': link.active }" /></div>
        </section>
    </AuthenticatedLayout>
</template>

<style scoped>
.filter-label { @apply mb-1.5 block text-xs font-bold uppercase tracking-wider text-[#60745d]; }
.filter-input { @apply w-full rounded-xl border-[#d8e7d4] text-sm focus:border-[#4f9f4a] focus:ring-[#4f9f4a]; }
</style>
